<?php use App\Core\View; ?>
<div class="page-head"><div><h1>Packs</h1><p>Contenedores pack → órdenes. No se usan para duplicar ventas.</p></div></div>
<section class="panel table-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Pack</th><th>Cuenta</th><th>Envío externo</th><th>Órdenes</th><th>Estado</th><th>Sync</th></tr></thead><tbody><?php if(!$packs):?><tr><td colspan="6"><div class="empty">Sin packs sincronizados.</div></td></tr><?php endif;?><?php foreach($packs as $pack):?><tr><td><?= View::e($pack['external_pack_id']) ?></td><td><?= View::e($pack['account_name']) ?></td><td><?= View::e($pack['external_shipment_id'] ?: '—') ?></td><td><?= (int)$pack['orders_count'] ?></td><td><span class="badge"><?= View::e($pack['status'] ?: '—') ?></span></td><td><?= View::e($pack['synced_at']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
